126	// NewAdapter is the constructor for Adapter.
127	// Params : databaseName,tableName,dbSpecified
128	//
129	//	databaseName,{tableName/dbSpecified}
130	//	{database/dbSpecified}
131	//
132	// databaseName and tableName are user defined.
133	// Their default value are "casbin" and "casbin_rule"
134	//
135	// dbSpecified is an optional bool parameter. The default value is false.
136	// It's up to whether you have specified an existing DB in dataSourceName.
137	// If dbSpecified == true, you need to make sure the DB in dataSourceName exists.
138	// If dbSpecified == false, the adapter will automatically create a DB named databaseName.
139	func NewAdapter(driverName string, dataSourceName string, params ...interface{}) (*Adapter, error) {
140		a := &Adapter{}
141		a.driverName = driverName
142		a.dataSourceName = dataSourceName
143	
144		a.tableName = defaultTableName
145		a.databaseName = defaultDatabaseName
146		a.dbSpecified = false
147		a.transactionMu = &sync.Mutex{}
148	
149		if len(params) == 1 {
150			switch p1 := params[0].(type) {
151			case bool:
152				a.dbSpecified = p1
153			case string:
154				a.databaseName = p1
155			default:
156				return nil, errors.New("wrong format")
157			}
158		} else if len(params) == 2 {
159			switch p2 := params[1].(type) {
160			case bool:
161				a.dbSpecified = p2
162				p1, ok := params[0].(string)
163				if !ok {
164					return nil, errors.New("wrong format")
165				}
166				a.databaseName = p1
167			case string:
168				p1, ok := params[0].(string)
169				if !ok {
170					return nil, errors.New("wrong format")
171				}
172				a.databaseName = p1
173				a.tableName = p2
174			default:
175				return nil, errors.New("wrong format")
176			}
177		} else if len(params) == 3 {
178			if p3, ok := params[2].(bool); ok {
179				a.dbSpecified = p3
180				a.databaseName = params[0].(string)
181				a.tableName = params[1].(string)
182			} else {
183				return nil, errors.New("wrong format")
184			}
185		} else if len(params) != 0 {
186			return nil, errors.New("too many parameters")
187		}
188	
189		// Open the DB, create it if not existed.
190		err := a.Open()
191		if err != nil {
192			return nil, err
193		}
194	
195		// Call the destructor when the object is released.
196		runtime.SetFinalizer(a, finalizer)
197	
198		return a, nil
199	}
