201	// NewAdapterByDBUseTableName creates gorm-adapter by an existing Gorm instance and the specified table prefix and table name
202	// Example: gormadapter.NewAdapterByDBUseTableName(&db, "cms", "casbin") Automatically generate table name like this "cms_casbin"
203	func NewAdapterByDBUseTableName(db *gorm.DB, prefix string, tableName string) (*Adapter, error) {
204		if len(tableName) == 0 {
205			tableName = defaultTableName
206		}
207	
208		a := &Adapter{
209			tablePrefix:   prefix,
210			tableName:     tableName,
211			transactionMu: &sync.Mutex{},
212		}
213	
214		a.db = db.Scopes(a.casbinRuleTable()).Session(&gorm.Session{Context: db.Statement.Context})
215	
216		err := a.createTable()
217		if err != nil {
218			return nil, err
219		}
220	
221		return a, nil
222	}
