224	// InitDbResolver multiple databases support
225	// Example usage:
226	// dbPool,err := InitDbResolver([]gorm.Dialector{mysql.Open(dsn),mysql.Open(dsn2)},[]string{"casbin1","casbin2"})
227	// a := initAdapterWithGormInstanceByMulDb(t,dbPool,"casbin1","","casbin_rule1")
228	// a = initAdapterWithGormInstanceByMulDb(t,dbPool,"casbin2","","casbin_rule2")/*
229	func InitDbResolver(dbArr []gorm.Dialector, dbNames []string) (DbPool, error) {
230		if len(dbArr) == 0 {
231			panic("dbArr len is 0")
232		}
233		source, e := gorm.Open(dbArr[0])
234		if e != nil {
235			panic(e.Error())
236		}
237		var p specificPolicy
238		p = 0
239		err := source.Use(dbresolver.Register(dbresolver.Config{Policy: &p, Sources: dbArr}))
240		dbMap := make(map[string]specificPolicy)
241		for i := 0; i < len(dbNames); i++ {
242			dbMap[dbNames[i]] = specificPolicy(i)
243		}
244		return DbPool{dbMap: dbMap, policy: &p, source: source}, err
245	}
