296	func TurnOffAutoMigrate(db *gorm.DB) {
297		ctx := db.Statement.Context
298		if ctx == nil {
299			ctx = context.Background()
300		}
301	
302		ctx = context.WithValue(ctx, disableMigrateKey, false)
303	
304		*db = *db.WithContext(ctx)
305	}
