307	func NewAdapterByDBWithCustomTable(db *gorm.DB, t interface{}, tableName ...string) (*Adapter, error) {
308		ctx := db.Statement.Context
309		if ctx == nil {
310			ctx = context.Background()
311		}
312	
313		ctx = context.WithValue(ctx, customTableKey, t)
314	
315		curTableName := defaultTableName
316		if len(tableName) > 0 {
317			curTableName = tableName[0]
318		}
319	
320		return NewAdapterByDBUseTableName(db.WithContext(ctx), "", curTableName)
321	}
