323	func openDBConnection(driverName, dataSourceName string) (*gorm.DB, error) {
324		var err error
325		var db *gorm.DB
326		config := &gorm.Config{
327			Logger: logger.Default.LogMode(logger.Silent),
328		}
329		if driverName == "postgres" {
330			db, err = gorm.Open(postgres.Open(dataSourceName), config)
331		} else if driverName == "mysql" {
332			db, err = gorm.Open(mysql.Open(dataSourceName), config)
333		} else if driverName == "sqlserver" {
334			db, err = gorm.Open(sqlserver.Open(dataSourceName), config)
335		} else if driverName == "sqlite3" {
336			db, err = gorm.Open(sqlite.Open(dataSourceName), config)
337		} else {
338			return nil, errors.New("Database dialect '" + driverName + "' is not supported. Supported databases are postgres, mysql, sqlserver and sqlite3")
339		}
340		if err != nil {
341			return nil, err
342		}
343		return db, err
344	}
