346	func (a *Adapter) createDatabase() error {
347		var err error
348		db, err := openDBConnection(a.driverName, a.dataSourceName)
349		if err != nil {
350			return err
351		}
352		if a.driverName == "postgres" {
353			if err = db.Exec("CREATE DATABASE " + a.databaseName).Error; err != nil {
354				// 42P04 is	duplicate_database
355				if strings.Contains(fmt.Sprintf("%s", err), "42P04") {
356					return nil
357				}
358			}
359		} else if a.driverName != "sqlite3" && a.driverName != "sqlserver" {
360			err = db.Exec("CREATE DATABASE IF NOT EXISTS " + a.databaseName).Error
361		}
362		if err != nil {
363			return err
364		}
365		return nil
366	}
367	
368	func (a *Adapter) Open() error {
369		var err error
370		var db *gorm.DB
371	
372		if a.dbSpecified {
373			db, err = openDBConnection(a.driverName, a.dataSourceName)
374			if err != nil {
375				return err
376			}
377		} else {
378			if err = a.createDatabase(); err != nil {
379				return err
380			}
381			if a.driverName == "postgres" {
382				db, err = openDBConnection(a.driverName, a.dataSourceName+" dbname="+a.databaseName)
383			} else if a.driverName == "sqlite3" {
384				db, err = openDBConnection(a.driverName, a.dataSourceName)
385			} else if a.driverName == "sqlserver" {
386				db, err = openDBConnection(a.driverName, a.dataSourceName+"?database="+a.databaseName)
387			} else {
388				db, err = openDBConnection(a.driverName, a.dataSourceName+a.databaseName)
389			}
390			if err != nil {
391				return err
392			}
393		}
394	
395		a.db = db.Scopes(a.casbinRuleTable()).Session(&gorm.Session{})
396		return a.createTable()
397	}
