431	func (a *Adapter) createTable() error {
432		disableMigrate := a.db.Statement.Context.Value(disableMigrateKey)
433		if disableMigrate != nil {
434			return nil
435		}
436	
437		t := a.db.Statement.Context.Value(customTableKey)
438	
439		if t != nil {
440			return a.db.AutoMigrate(t)
441		}
442	
443		t = a.getTableInstance()
444		if err := a.db.AutoMigrate(t); err != nil {
445			return err
446		}
447	
448		tableName := a.getFullTableName()
449		index := strings.ReplaceAll("idx_"+tableName, ".", "_")
450		hasIndex := a.db.Migrator().HasIndex(t, index)
451		if !hasIndex {
452			if err := a.db.Exec(fmt.Sprintf("CREATE UNIQUE INDEX %s ON %s (ptype,v0,v1,v2,v3,v4,v5)", index, tableName)).Error; err != nil {
453				return err
454			}
455		}
456		return nil
457	}
