459	func (a *Adapter) dropTable() error {
460		t := a.db.Statement.Context.Value(customTableKey)
461		if t == nil {
462			return a.db.Migrator().DropTable(a.getTableInstance())
463		}
464	
465		return a.db.Migrator().DropTable(t)
466	}
