468	func (a *Adapter) truncateTable() error {
469		var sql string
470		switch a.db.Config.Name() {
471		case sqlite.DriverName:
472			sql = fmt.Sprintf("delete from %s", a.getFullTableName())
473		case "sqlite3":
474			sql = fmt.Sprintf("delete from %s", a.getFullTableName())
475		case "postgres":
476			sql = fmt.Sprintf("truncate table %s RESTART IDENTITY", a.getFullTableName())
477		case "sqlserver":
478			sql = fmt.Sprintf("truncate table %s", a.getFullTableName())
479		case "mysql":
480			sql = fmt.Sprintf("truncate table %s", a.getFullTableName())
481		default:
482			sql = fmt.Sprintf("truncate table %s", a.getFullTableName())
483		}
484		return a.db.Exec(sql).Error
485	}
