487	func loadPolicyLine(line CasbinRule, model model.Model) error {
488		var p = []string{line.Ptype,
489			line.V0, line.V1, line.V2,
490			line.V3, line.V4, line.V5}
491	
492		index := len(p) - 1
493		for p[index] == "" {
494			index--
495		}
496		index += 1
497		p = p[:index]
498		err := persist.LoadPolicyArray(p, model)
499		if err != nil {
500			return err
501		}
502		return nil
503	}
