510	// LoadPolicyCtx loads policy from database.
511	func (a *Adapter) LoadPolicyCtx(ctx context.Context, model model.Model) error {
512		var lines []CasbinRule
513		if err := a.db.WithContext(ctx).Order("ID").Find(&lines).Error; err != nil {
514			return err
515		}
516		err := a.Preview(&lines, model)
517		if err != nil {
518			return err
519		}
520		for _, line := range lines {
521			err := loadPolicyLine(line, model)
522			if err != nil {
523				return err
524			}
525		}
526	
527		return nil
528	}
