530	// LoadFilteredPolicy loads only policy rules that match the filter.
531	func (a *Adapter) LoadFilteredPolicy(model model.Model, filter interface{}) error {
532		var lines []CasbinRule
533	
534		batchFilter := BatchFilter{
535			filters: []Filter{},
536		}
537		switch filterValue := filter.(type) {
538		case Filter:
539			batchFilter.filters = []Filter{filterValue}
540		case *Filter:
541			batchFilter.filters = []Filter{*filterValue}
542		case []Filter:
543			batchFilter.filters = filterValue
544		case BatchFilter:
545			batchFilter = filterValue
546		case *BatchFilter:
547			batchFilter = *filterValue
548		default:
549			return errors.New("unsupported filter type")
550		}
551	
552		for _, f := range batchFilter.filters {
553			if err := a.db.Scopes(a.filterQuery(a.db, f)).Order("ID").Find(&lines).Error; err != nil {
554				return err
555			}
556	
557			for _, line := range lines {
558				err := loadPolicyLine(line, model)
559				if err != nil {
560					return err
561				}
562			}
563		}
564		a.isFiltered = true
565	
566		return nil
567	}
