574	// filterQuery builds the gorm query to match the rule filter to use within a scope.
575	func (a *Adapter) filterQuery(db *gorm.DB, filter Filter) func(db *gorm.DB) *gorm.DB {
576		return func(db *gorm.DB) *gorm.DB {
577			if len(filter.Ptype) > 0 {
578				db = db.Where("ptype in (?)", filter.Ptype)
579			}
580			if len(filter.V0) > 0 {
581				db = db.Where("v0 in (?)", filter.V0)
582			}
583			if len(filter.V1) > 0 {
584				db = db.Where("v1 in (?)", filter.V1)
585			}
586			if len(filter.V2) > 0 {
587				db = db.Where("v2 in (?)", filter.V2)
588			}
589			if len(filter.V3) > 0 {
590				db = db.Where("v3 in (?)", filter.V3)
591			}
592			if len(filter.V4) > 0 {
593				db = db.Where("v4 in (?)", filter.V4)
594			}
595			if len(filter.V5) > 0 {
596				db = db.Where("v5 in (?)", filter.V5)
597			}
598			return db
599		}
600	}
