602	func (a *Adapter) savePolicyLine(ptype string, rule []string) CasbinRule {
603		line := a.getTableInstance()
604	
605		line.Ptype = ptype
606		if len(rule) > 0 {
607			line.V0 = rule[0]
608		}
609		if len(rule) > 1 {
610			line.V1 = rule[1]
611		}
612		if len(rule) > 2 {
613			line.V2 = rule[2]
614		}
615		if len(rule) > 3 {
616			line.V3 = rule[3]
617		}
618		if len(rule) > 4 {
619			line.V4 = rule[4]
620		}
621		if len(rule) > 5 {
622			line.V5 = rule[5]
623		}
624	
625		return *line
626	}
