633	// SavePolicyCtx saves policy to database.
634	func (a *Adapter) SavePolicyCtx(ctx context.Context, model model.Model) error {
635		var err error
636		tx := a.db.WithContext(ctx).Clauses(dbresolver.Write).Begin()
637	
638		err = a.truncateTable()
639	
640		if err != nil {
641			tx.Rollback()
642			return err
643		}
644	
645		var lines []CasbinRule
646		flushEvery := 1000
647		for ptype, ast := range model["p"] {
648			for _, rule := range ast.Policy {
649				lines = append(lines, a.savePolicyLine(ptype, rule))
650				if len(lines) > flushEvery {
651					if err := tx.Clauses(clause.OnConflict{DoNothing: true}).Create(&lines).Error; err != nil {
652						tx.Rollback()
653						return err
654					}
655					lines = nil
656				}
657			}
658		}
659	
660		for ptype, ast := range model["g"] {
661			for _, rule := range ast.Policy {
662				lines = append(lines, a.savePolicyLine(ptype, rule))
663				if len(lines) > flushEvery {
664					if err := tx.Clauses(clause.OnConflict{DoNothing: true}).Create(&lines).Error; err != nil {
665						tx.Rollback()
666						return err
667					}
668					lines = nil
669				}
670			}
671		}
672		if len(lines) > 0 {
673			if err := tx.Clauses(clause.OnConflict{DoNothing: true}).Create(&lines).Error; err != nil {
674				tx.Rollback()
675				return err
676			}
677		}
678	
679		err = tx.Commit().Error
680		return err
681	}
