727	// Transaction perform a set of operations within a transaction.
728	func (a *Adapter) Transaction(e casbin.IEnforcer, fc func(casbin.IEnforcer) error, opts ...*sql.TxOptions) error {
729		// ensure the transactionMu is initialized
730		if a.transactionMu == nil {
731			a.muInitialize.Do(func() {
732				if a.transactionMu == nil {
733					a.transactionMu = &sync.Mutex{}
734				}
735			})
736		}
737	
738		// check adapter type
739		adapter, ok := e.GetAdapter().(*Adapter)
740		if !ok {
741			return errors.New("expected adapter of type Adapter, but got incompatible type")
742		}
743	
744		// check if we're already in a transaction by checking if the current adapter is a transaction adapter
745		if _, isTxAdapter := adapter.db.Statement.ConnPool.(*sql.Tx); isTxAdapter {
746			// we're already in a transaction, create a savepoint for nested transaction
747			savepointName := fmt.Sprintf("casbin_nested_%d", time.Now().UnixNano())
748	
749			// create savepoint
750			if err := adapter.db.SavePoint(savepointName).Error; err != nil {
751				return errors.Wrap(err, "failed to create savepoint for nested transaction")
752			}
753	
754			// save model state before inner transaction
755			originalModel := e.GetModel().Copy()
756	
757			err := fc(e)
758			if err != nil {
759				// rollback database changes
760				if rollbackErr := adapter.db.RollbackTo(savepointName).Error; rollbackErr != nil {
761					return errors.Wrap(rollbackErr, "failed to rollback savepoint")
762				}
763				// restore model state to undo inner transaction changes
764				e.SetModel(originalModel)
765				fmt.Printf("Warning: Inner transaction failed and was rolled back: %v\n", err)
766				// Don't return error to allow outer transaction to continue
767				return nil
768			}
769	
770			return nil
771		}
772	
773		// lock the transactionMu to ensure the transaction is thread-safe
774		a.transactionMu.Lock()
775		defer a.transactionMu.Unlock()
776	
777		// save original adapter
778		originalAdapter := adapter.Copy()
779	
780		// use GORM transaction functionality
781		err := adapter.db.Transaction(func(tx *gorm.DB) error {
782			// create transaction adapter
783			txAdapter, err := NewAdapterByDB(tx)
784			if err != nil {
785				return errors.Wrap(err, "failed to initialize gorm adapter")
786			}
787	
788			// temporarily set transaction adapter
789			e.SetAdapter(txAdapter)
790	
791			// execute transaction function
792			err = fc(e)
793			if err != nil {
794				return errors.Wrap(err, "failed transactional policy operations")
795			}
796	
797			return nil
798		}, opts...)
799	
800		// restore original adapter
801		e.SetAdapter(originalAdapter)
802	
803		if err != nil {
804			// LoadPolicy is called only when the transaction encounters an error and fails.
805			// While this operation is expensive, failures are rare due to validation at earlier layers.
806			// When a transaction fails, the in-memory model may be out of sync, so LoadPolicy is needed
807			// to restore consistency by reloading from the database.
808			if loadErr := e.LoadPolicy(); loadErr != nil {
809				return errors.Wrap(loadErr, "failed to load policy after transaction failure")
810			}
811			return errors.Wrap(err, "transaction execution failed")
812		}
813	
814		return nil
815	}
