817	// BeginTransaction implements TransactionalAdapter interface.
818	// It starts a new database transaction and returns a TransactionContext.
819	func (a *Adapter) BeginTransaction(ctx context.Context) (persist.TransactionContext, error) {
820		// Start GORM database transaction
821		tx := a.db.WithContext(ctx).Begin()
822		if tx.Error != nil {
823			return nil, tx.Error
824		}
825	
826		return &GormTransactionContext{
827			tx:        tx,
828			ctx:       ctx,
829			adapter:   a,
830			tableName: a.tableName,
831		}, nil
832	}
