834	// GormTransactionContext implements persist.TransactionContext interface.
835	// It provides transaction control methods and returns a transaction-aware adapter.
836	type GormTransactionContext struct {
837		tx         *gorm.DB
838		ctx        context.Context
839		adapter    *Adapter
840		tableName  string
841		committed  bool
842		rolledBack bool
843	}
844	
845	// Commit commits the database transaction.
846	func (gtx *GormTransactionContext) Commit() error {
847		if gtx.committed || gtx.rolledBack {
848			return errors.New("transaction already finished")
849		}
850	
851		err := gtx.tx.Commit().Error
852		if err == nil {
853			gtx.committed = true
854		}
855		return err
856	}
857	
858	// Rollback rolls back the database transaction.
859	func (gtx *GormTransactionContext) Rollback() error {
860		if gtx.committed || gtx.rolledBack {
861			return errors.New("transaction already finished")
862		}
863	
864		err := gtx.tx.Rollback().Error
865		if err == nil {
866			gtx.rolledBack = true
867		}
868		return err
869	}
870	
871	// GetAdapter returns an adapter that operates within this transaction.
872	// All policy operations through this adapter will be part of the transaction.
873	func (gtx *GormTransactionContext) GetAdapter() persist.Adapter {
874		return &Adapter{
875			driverName:     gtx.adapter.driverName,
876			dataSourceName: gtx.adapter.dataSourceName,
877			databaseName:   gtx.adapter.databaseName,
878			tablePrefix:    gtx.adapter.tablePrefix,
879			tableName:      gtx.tableName,
880			dbSpecified:    gtx.adapter.dbSpecified,
881			db:             gtx.tx, // Use transaction connection
882			isFiltered:     gtx.adapter.isFiltered,
883			// Note: No transactionMu needed as each transaction has its own adapter
884		}
885	}
