1027	func (a *Adapter) UpdatePolicies(sec string, ptype string, oldRules, newRules [][]string) error {
1028		oldPolicies := make([]CasbinRule, 0, len(oldRules))
1029		newPolicies := make([]CasbinRule, 0, len(oldRules))
1030		for _, oldRule := range oldRules {
1031			oldPolicies = append(oldPolicies, a.savePolicyLine(ptype, oldRule))
1032		}
1033		for _, newRule := range newRules {
1034			newPolicies = append(newPolicies, a.savePolicyLine(ptype, newRule))
1035		}
1036		tx := a.db.Begin()
1037		for i := range oldPolicies {
1038			if err := tx.Model(&oldPolicies[i]).Where(&oldPolicies[i]).Updates(newPolicies[i]).Error; err != nil {
1039				tx.Rollback()
1040				return err
1041			}
1042		}
1043		return tx.Commit().Error
