1048		line := a.getTableInstance()
1049	
1050		line.Ptype = ptype
1051		if fieldIndex <= 0 && 0 < fieldIndex+len(fieldValues) {
1052			line.V0 = fieldValues[0-fieldIndex]
1053		}
1054		if fieldIndex <= 1 && 1 < fieldIndex+len(fieldValues) {
1055			line.V1 = fieldValues[1-fieldIndex]
1056		}
1057		if fieldIndex <= 2 && 2 < fieldIndex+len(fieldValues) {
1058			line.V2 = fieldValues[2-fieldIndex]
1059		}
1060		if fieldIndex <= 3 && 3 < fieldIndex+len(fieldValues) {
1061			line.V3 = fieldValues[3-fieldIndex]
1062		}
1063		if fieldIndex <= 4 && 4 < fieldIndex+len(fieldValues) {
1064			line.V4 = fieldValues[4-fieldIndex]
1065		}
1066		if fieldIndex <= 5 && 5 < fieldIndex+len(fieldValues) {
1067			line.V5 = fieldValues[5-fieldIndex]
1068		}
1069	
1070		newP := make([]CasbinRule, 0, len(newPolicies))
1071		oldP := make([]CasbinRule, 0)
1072		for _, newRule := range newPolicies {
1073			newP = append(newP, a.savePolicyLine(ptype, newRule))
1074		}
1075	
1076		tx := a.db.Begin()
1077		str, args := line.queryString()
1078		if err := tx.Where(str, args...).Find(&oldP).Error; err != nil {
1079			tx.Rollback()
1080			return nil, err
1081		}
1082		if err := tx.Where(str, args...).Delete([]CasbinRule{}).Error; err != nil {
1083			tx.Rollback()
1084			return nil, err
1085		}
1086		for i := range newP {
1087			if err := tx.Clauses(clause.OnConflict{DoNothing: true}).Create(&newP[i]).Error; err != nil {
1088				tx.Rollback()
1089				return nil, err
1090			}
1091		}
1092	
1093		// return deleted rulues
1094		oldPolicies := make([][]string, 0)
1095		for _, v := range oldP {
1096			oldPolicy := v.toStringPolicy()
1097			oldPolicies = append(oldPolicies, oldPolicy)
1098		}
1099		return oldPolicies, tx.Commit().Error
1100	}
