1117	// Preview Pre-checking to avoid causing partial load success and partial failure deep
1118	func (a *Adapter) Preview(rules *[]CasbinRule, model model.Model) error {
1119		j := 0
1120		for i, rule := range *rules {
1121			r := []string{rule.Ptype,
1122				rule.V0, rule.V1, rule.V2,
1123				rule.V3, rule.V4, rule.V5}
1124			index := len(r) - 1
1125			for r[index] == "" {
1126				index--
1127			}
1128			index += 1
1129			p := r[:index]
1130			key := p[0]
1131			sec := key[:1]
1132			ok, err := model.HasPolicyEx(sec, key, p[1:])
1133			if err != nil {
1134				return err
1135			}
1136			if ok {
1137				(*rules)[j], (*rules)[i] = rule, (*rules)[j]
1138				j++
1139			}
1140		}
1141		(*rules) = (*rules)[j:]
1142		return nil
1143	}
