1207	// CombineType represents different types of condition combining strategies
1208	type CombineType uint32
1209	
1210	const (
1211		CombineTypeOr  CombineType = iota // Combine conditions with OR operator
1212		CombineTypeAnd                    // Combine conditions with AND operator
1213	)
1214	
1215	// ConditionsToGormQuery is a function that converts multiple query conditions into a GORM query statement
1216	// You can use the GetAllowedObjectConditions() API of Casbin to get conditions,
1217	// and choose the way of combining conditions through combineType.
1218	func ConditionsToGormQuery(db *gorm.DB, conditions []string, combineType CombineType) *gorm.DB {
1219		queryDB := db
1220		for _, cond := range conditions {
1221			switch combineType {
1222			case CombineTypeOr:
1223				queryDB = queryDB.Or(cond)
1224			case CombineTypeAnd:
1225				queryDB = queryDB.Where(cond)
1226			}
1227		}
1228		return queryDB
1229	}
