func TestAddPolicy(t *testing.T) {
	tests := []struct {
		driverName     string
		dataSourceName string
		params         []any
	}{
		{"mysql", "root:@tcp(127.0.0.1:3306)/", []any{"casbin", "casbin_rule"}},
		{"postgres", "user=postgres password=postgres host=127.0.0.1 port=5432 sslmode=disable", nil},
